"""Cross-language parity: fixtures generated by @paretomol/core, checked here."""

from __future__ import annotations

import json
from pathlib import Path

from paretomol import (
    Molecule,
    build_decision_record,
    canonical_json,
    canonical_property,
    compute_pareto,
    decode_review,
    expected_direction,
    get_profile,
    infer_objective_direction,
    infer_objectives,
    list_profiles,
    mpo_score,
    parse_decision_record,
    review_token_from_url,
    review_url,
    round6,
    selected_indices,
    sha256_hex,
    stringify_decision_record,
    validate_review,
)

FIX = json.loads((Path(__file__).parent / "fixtures" / "golden.json").read_text(encoding="utf-8"))


def _mols(specs):
    out = []
    for spec in specs:
        out.append(Molecule(
            spec["name"],
            spec.get("smiles") or spec["name"],
            spec.get("props") or {},
            spec.get("customProps") or {},
        ))
    return out


def test_sha256_and_canonical_json():
    for row in FIX["sha256"]:
        assert sha256_hex(row["input"]) == row["hex"]
    for row in FIX["canonical"]:
        assert canonical_json(row["value"]) == row["json"]


def test_profile_hashes_match_core():
    assert sorted(p.ref for p in list_profiles()) == sorted(FIX["profiles"])
    for ref, info in FIX["profiles"].items():
        profile = get_profile(ref)
        assert profile.hash == info["hash"]
        assert profile.ref == info["ref"]
        assert canonical_json(profile.body) == info["canonical"]
    assert get_profile("oral").hash == get_profile("oral@1").hash


def test_objective_directions_match_core():
    for row in FIX["directions"]:
        assert infer_objective_direction(row["name"]) == row["direction"]
    assert infer_objectives(FIX["inferObjectives"]["names"]) == FIX["inferObjectives"]["objectives"]
    for row in FIX["expectedDirection"]:
        assert expected_direction(row["key"]) == row["direction"]
    for row in FIX["canonicalProperty"]:
        assert canonical_property(row["key"]) == row["property"]


def test_mpo_scores_match_core():
    for key, row in FIX["mpo"].items():
        ref, curve = key.split("/")
        window = get_profile(ref).desirability
        for name, expected in row.items():
            score = round6(mpo_score(FIX["mpoProps"][name], window, curve)["score"])
            assert score == expected, (key, name, score, expected)


def test_pareto_ranks_match_core():
    for case in FIX["pareto"]:
        mols = _mols(case["molecules"])
        compute_pareto(mols, case["objectives"])
        assert [m.pareto_rank for m in mols] == case["ranks"]
        assert [m.missing_objectives for m in mols] == case["missing"]
        assert [m.dominates for m in mols] == case["dominates"]
        assert [m.dominated_by for m in mols] == case["dominatedBy"]


def _build(case, molecules=None):
    return build_decision_record(
        molecules if molecules is not None else case["molecules"],
        case["objectives"],
        profile=case["profile"],
        selected=case["selected"],
        rationale=case["rationale"],
        rdkit_version=case["rdkitVersion"],
        admet_endpoint=case["admetEndpoint"] or None,
        view=case["view"] or None,
        review=case["review"] or None,
        timestamp=case["timestamp"],
    )


def test_decision_records_match_core():
    texts = {}
    for case in FIX["decisions"]:
        rec = _build(case)
        text = stringify_decision_record(rec)
        assert text == case["text"]
        assert rec["recordHash"] == case["recordHash"]
        assert rec["input"]["sha256"] == case["inputHash"]
        parsed = parse_decision_record(text)
        assert parsed["recordHash"] == case["recordHash"]
        assert stringify_decision_record(parsed) == text
        texts[case["id"]] = case
    assert texts["base"]["inputHash"] == texts["later"]["inputHash"]
    assert texts["base"]["recordHash"] != texts["later"]["recordHash"]


def test_ranked_decision_recomputes_to_the_same_record():
    case = next(c for c in FIX["decisions"] if c["id"] == "ranked")
    mols = _mols(case["molecules"])
    for mol, spec in zip(mols, case["molecules"]):
        mol.smiles = spec["smiles"]
    compute_pareto(mols, case["objectives"])
    rec = _build(case, mols)
    assert stringify_decision_record(rec) == case["text"]
    assert selected_indices(rec) == [1]


def test_review_urls_match_core():
    # Deflate bytes differ between fflate and zlib, so the characters of the
    # token are not shared. Both sides must open the TypeScript link, and a
    # Python link must round-trip to the same payload.
    for case in FIX["review"]:
        expect = validate_review(case["input"])
        url = review_url(case["input"])
        assert url.startswith("https://paretomol.com/#r=v1.")
        assert decode_review(review_token_from_url(url)) == expect
        assert decode_review(review_token_from_url(case["url"])) == expect
